function updatePorts(nodeId, parameters, editorConnection) {
  const numInputs = Math.max(0, Math.floor(parameters.numInputs || 3));
  const ports = [];

  ports.push(
    {
      type: 'signal',
      plug: 'input',
      group: 'Control',
      name: 'update',
      displayName: 'Update'
    },
    {
      type: 'signal',
      plug: 'input',
      group: 'Control',
      name: 'reset',
      displayName: 'Reset'
    },
    {
      type: 'number',
      plug: 'input',
      group: 'Configuration',
      name: 'numInputs',
      displayName: 'Number of Inputs'
    }
  );

  for (let i = 0; i < numInputs; i++) {
    const inputName = `input${i}`;
    const outputName = `output${i}`;
    const aliasName = `alias${i}`;

    const aliasValue = parameters[aliasName];
    const displayName = aliasValue || `${i}`;

    ports.push({
      type: '*',
      plug: 'input',
      group: 'Inputs',
      name: inputName,
      displayName: `Input ${displayName}`
    });

    ports.push({
      type: 'string',
      plug: 'input',
      group: 'Aliases',
      name: aliasName,
      displayName: `Alias ${i}`,
      default: ''
    });

    ports.push({
      type: 'array',
      plug: 'output',
      group: 'Outputs',
      name: outputName,
      displayName: `Output ${displayName}`
    });
  }

  ports.push(
    {
      type: 'signal',
      plug: 'output',
      group: 'Control',
      name: 'updated',
      displayName: 'Updated'
    },
    {
      type: 'signal',
      plug: 'output',
      group: 'Control',
      name: 'Reset Done',
      displayName: 'Reset Done'
    }
  );

  editorConnection.sendDynamicPorts(nodeId, ports, {
    detectRenamed: [
      {
        plug: 'input',
        prefix: 'input'
      },
      {
        plug: 'output',
        prefix: 'output'
      }
    ]
  });
}

function setupNodeEvents(node) {
      const numInputs = Math.max(0, Math.floor(node.parameters.numInputs || 3));
      for (let i = 0; i < numInputs; i++) {
        const aliasName = `alias${i}`;
        const aliasValue = node.parameters[aliasName];
        if (aliasValue) {
          node._internal.aliases[aliasName] = aliasValue;
        }
      }

      updatePorts(node.id, node.parameters, context.editorConnection);

      node.on('parameterUpdated', function (event) {
        if (event.name === 'numInputs' || event.name.startsWith('alias')) {
          updatePorts(node.id, node.parameters, context.editorConnection);
        }
      });
    }
